def zip_dict(ks, vs):
    """Return a dictionary that maps the first elements of `ks` to
    the corresponding elements of `vs`. If `vs` has fewer elements
    than `ks`, missing values are replaced with ``None``; extra values
    in `vs` are ignored. Only the standard library is used.
    """
    try:
        k_list = list(ks)
    except TypeError:
        # `ks` is not iterable
        raise TypeError("ks must be an iterable")

    try:
        v_list = list(vs)
    except TypeError:
        # `vs` is not iterable
        raise TypeError("vs must be an iterable")

    result = {}
    for i, key in enumerate(k_list):
        # Grab the value if it exists, otherwise use None
        result[key] = v_list[i] if i < len(v_list) else None
    return result
